title: "二次関数は何を表す関数か",
body: "二次関数は、最初に見ると $y=ax^2+bx+c$ という式の形だけが印象に残りやすい単元です。\n\nしかし、二次関数で本当に大切なのは、式を暗記することではありません。大切なのは、**変化のしかたが変化する関数**だと理解することです。\n\n一次関数 $y=ax+b$ では、$x$ が $1$ 増えるたびに $y$ は一定の量だけ増えたり減ったりします。だからグラフは直線になります。\n\n一方、二次関数では $x^2$ の項があるため、$x$ が増えたときの $y$ の増え方そのものが変わっていきます。最初はゆっくり増えていたのに、だんだん急に増える。あるいは、最初は減っていたのに、途中から増え始める。このような変化が起こります。\n\nその結果、グラフは直線ではなく、曲線になります。この曲線を**放物線**と呼びます。",
