kind: "concept",
title: "一次関数との違い",
body: "一次関数と二次関数の違いを、式だけでなく変化のしかたで見てみます。\n\n一次関数 $y=2x+1$ を考えます。$x$ が $1$ 増えると、$y$ はいつも $2$ ずつ増えます。\n\n$x=0$ のとき $y=1$\n\n$x=1$ のとき $y=3$\n\n$x=2$ のとき $y=5$\n\n$x=3$ のとき $y=7$\n\n増え方は常に $+2$ です。だから一直線になります。\n\n次に、二次関数 $y=x^2$ を考えます。\n\n$x=0$ のとき $y=0$\n\n$x=1$ のとき $y=1$\n\n$x=2$ のとき $y=4$\n\n$x=3$ のとき $y=9$\n\n増え方は、$0$ から $1$、$1$ から $4$、$4$ から $9$ なので、$+1$、$+3$、$+5$ と変わっていきます。\n\nこのように、二次関数では $y$ の増え方が一定ではありません。ここが一次関数との大きな違いです。",
