title: "この講座のゴール",
body: "共有点・解の個数問題の標準手順は、まず $f(x)=g(x)$ を立てることです。整理後が二次方程式なら判別式 $D$ を見れば、実数解が2個・1個・0個のどれかを判定できます。\n\nただし、ここで止まると危険です。判別式は、**整理後の二次方程式が実数解を何個もつか**しか見ていません。元の問題でその解が有効か、定義域に入っているか、分母を0にしていないか、平方根の条件を満たすか、二次方程式のつもりが一次式や恒等式になっていないかは、別に確認する必要があります。\n\nこの講座では、共有点・解の個数を Core / Branch / Trap / Synthesis の4層で整理します。公式暗記ではなく、初手・分岐・例外・検算まで判断できる状態を目標にします。",
emphasis: "判別式は、整理後の二次方程式の実数解の個数だけを見る。元の問題で有効かは別確認。",
