title: "Trap：判別式が壊れる事故パターン",
body: "事故の原因は、判別式が見ていない情報にあります。判別式は、整理後の二次方程式の実数解の個数だけを見ます。つまり、定義域、除外値、根号条件、両辺2乗による余分な解、式で割って落とした解、最高次係数が0になる場合、完全一致や矛盾は見ていません。\n\n共有点問題では、判別式に入る前と後に必ず確認を入れます。前では、整理後が本当に二次方程式か。後では、出た解が元の式の条件を満たすか。この2段階チェックが事故を防ぎます。",
