kind: "workedExample",
title: "例4：定義域が動く問題",
body: "$t\\leq x\\leq t+2$ における $f(x)=x^2$ の最小値を求めます。\n\nこの問題では、関数 $f(x)=x^2$ の軸は $x=0$ で固定です。しかし、定義域 $[t,t+2]$ が $t$ によって動きます。\n\n最小値は、軸 $x=0$ が定義域に入っているかどうかで変わります。\n\n定義域がすべて正の側にある場合、つまり $t>0$ のとき、区間 $[t,t+2]$ の中で $0$ に最も近いのは左端 $x=t$ です。したがって最小値は $t^2$ です。\n\n定義域が $0$ を含む場合、つまり $t\\leq0\\leq t+2$ のとき、$-2\\leq t\\leq0$ です。この場合、$x=0$ が使えるので最小値は $0$ です。\n\n定義域がすべて負の側にある場合、つまり $t+2<0$、すなわち $t<-2$ のとき、$0$ に最も近いのは右端 $x=t+2$ です。したがって最小値は $(t+2)^2$ です。\n\nまとめると、\n\n$t<-2$ のとき $(t+2)^2$\n\n$-2\\leq t\\leq0$ のとき $0$\n\n$t>0$ のとき $t^2$\n\nとなります。\n\nこの問題は、軸が動くのではなく、定義域が動く問題です。何が動いているのかを最初に見抜くことが重要です。",
