title: "Core例題1：2解がともに正",
body: "**問題**：方程式 $x^2-2ax+a^2-1=0$ の2つの解がともに正となる $a$ の範囲を求めよ。\n\n**標準解答**：左辺は $(x-a)^2-1$ なので、解は $x=a-1,a+1$ です。2つとも正であるには $a-1>0$ かつ $a+1>0$。強い方は $a>1$ なので、答えは $a>1$ です。\n\n**別解**：解と係数の関係で見ると、2解を $\\alpha,\\beta$ として、$\\alpha+\\beta=2a$、$\\alpha\\beta=a^2-1$。2解がともに正なら、実数解があり、和が正、積が正です。この方程式は常に実数解をもち、条件は $2a>0$、$a^2-1>0$。よって $a>1$ または $a<-1$ のうち和が正な $a>1$ です。\n\n**検算**：$a=2$ なら解は $1,3$。$a=0$ なら解は $-1,1$ で失敗。境界 $a=1$ では解が $0,2$ なので「正」ではありません。",
emphasis: "正の解は、境界0を含まない。$a=1$ を入れない。",
