kind: "intro",
title: "この講座のゴール",
body: "整数条件が絡む二次関数では、まず**何が整数なのか**を固定します。$x$ が整数なのか、解が整数なのか、点 $(x,y)$ の両方が整数なのか、値 $y$ が整数なのか、整数の個数を数えるのかで、使う道具が変わります。\n\n中心メッセージは、整数条件の本質は方程式を解くことだけではない、ということです。整数解なら判別式の平方数条件・因数分解・解と係数の関係を使います。整数点なら、区間内の整数 $x$ を数え、対応する $y$ が整数かを確認します。整数個数なら、開区間・閉区間・端点・重複を最後まで確認します。",
emphasis: "最初に決めるのは、整数なのが「解」か「点」か「値」か「個数」か。",
