kind: "intro",
title: "この講座のゴール",
body: "絶対値・平方根・分数が二次関数に混ざると、問題は急に難しく見えます。しかし本質は、変形そのものではなく、**変形によって何が失われるか**を管理することです。\n\n絶対値なら中身の符号で場合分けします。平方根なら根号内が $0$ 以上で、方程式 $\\sqrt A=B$ では右辺 $B$ も $0$ 以上です。分数なら分母が $0$ でない条件を先に持ち、約分で消えた値を解に戻してはいけません。\n\nこの講座では、絶対値・平方根・分数を「定義条件 → 変形 → 元の式で確認」の流れで処理し、グラフ・値域・共有点・個数問題へつなげます。",
emphasis: "融合問題の合言葉は、定義条件を先に、元の式で最後に確認。",
