kind: "workedExample",
title: "Core例題1：$|f(x)|$ のグラフを読む",
body: "**問題**：$f(x)=x^2-4x+3$ とする。$y=|f(x)|$ のグラフの作り方を説明せよ。\n\n**標準解答**：$f(x)=(x-2)^2-1$ なので、放物線は $x=2$ を軸に下に1だけ沈んでいます。$f(x)<0$ となるのは $1<x<3$。したがって $y=|f(x)|$ は、$1<x<3$ の部分だけを $x$ 軸に関して上へ折り返したグラフです。\n\n**別解**：式で見れば、$x\\leq1$ または $x\\geq3$ では $|f(x)|=f(x)$、$1<x<3$ では $|f(x)|=-f(x)$ です。\n\n**よくあるミス**：グラフ全体を上に平行移動すること。絶対値は、負の部分を折り返す操作です。",
