function mergeQuadraticLinks(baseLinks: CourseLesson["relatedPracticeLinks"], extraLinks: CourseLesson["relatedPracticeLinks"]): CourseLesson["relatedPracticeLinks"] {
  const linksByHref = new Map<string, CourseLesson["relatedPracticeLinks"][number]>();
  for (const link of [...baseLinks, ...extraLinks]) {
    if (!linksByHref.has(link.href)) linksByHref.set(link.href, link);
  }
  return Array.from(linksByHref.values());
}

function insertQuadraticBlocks(lessonBlocks: CourseLesson["lessonBlocks"], enhancement: QuadraticEnhancement): CourseLesson["lessonBlocks"] {
  const leadInsertIndex = Math.max(1, lessonBlocks.findIndex((block) => block.kind !== "intro"));
  const withLeadBlocks = [...lessonBlocks.slice(0, leadInsertIndex), ...enhancement.leadBlocks, ...lessonBlocks.slice(leadInsertIndex)];
  const summaryIndex = withLeadBlocks.findIndex((block) => block.kind === "summary");
  if (summaryIndex === -1) return [...withLeadBlocks, ...enhancement.aftercareBlocks];
  return [...withLeadBlocks.slice(0, summaryIndex), ...enhancement.aftercareBlocks, ...withLeadBlocks.slice(summaryIndex)];
}

function enhanceQuadraticLesson(lesson: CourseLesson): CourseLesson {
  const enhancement = QUADRATIC_ENHANCEMENTS[lesson.lessonId];
  const maxMinDomainLinks = QUADRATIC_MAX_MIN_DOMAIN_BRIDGE_LESSON_IDS.has(lesson.lessonId)
    ? QUADRATIC_MAX_MIN_DOMAIN_LINK
    : [];
  const paramFunctionLinks = QUADRATIC_PARAM_FUNCTION_BRIDGE_LESSON_IDS.has(lesson.lessonId)
    ? QUADRATIC_PARAM_FUNCTION_LINK
    : [];
  const rootPlacementLinks = QUADRATIC_ROOT_PLACEMENT_BRIDGE_LESSON_IDS.has(lesson.lessonId)
    ? QUADRATIC_ROOT_PLACEMENT_LINK
    : [];
  const integerSolutionsPointsLinks = QUADRATIC_INTEGER_SOLUTIONS_POINTS_BRIDGE_LESSON_IDS.has(lesson.lessonId)
    ? QUADRATIC_INTEGER_SOLUTIONS_POINTS_LINK
    : [];
  const absoluteRadicalRationalLinks = QUADRATIC_ABSOLUTE_RADICAL_RATIONAL_BRIDGE_LESSON_IDS.has(lesson.lessonId)
    ? QUADRATIC_ABSOLUTE_RADICAL_RATIONAL_LINK
    : [];
  if (!enhancement) {
    if (
      maxMinDomainLinks.length === 0 &&
      paramFunctionLinks.length === 0 &&
      rootPlacementLinks.length === 0 &&
      integerSolutionsPointsLinks.length === 0 &&
      absoluteRadicalRationalLinks.length === 0
    ) return lesson;
    return {
      ...lesson,
      relatedPracticeLinks: mergeQuadraticLinks(lesson.relatedPracticeLinks, [
        ...maxMinDomainLinks,
        ...paramFunctionLinks,
        ...rootPlacementLinks,
        ...integerSolutionsPointsLinks,
        ...absoluteRadicalRationalLinks,
      ]),
    };
  }
  const bridgeLinks = QUADRATIC_INTERSECTION_BRIDGE_LESSON_IDS.has(lesson.lessonId)
    ? QUADRATIC_INTERSECTION_ROOT_COUNT_LINK
    : [];
  return {
    ...lesson,
    lessonBlocks: insertQuadraticBlocks(lesson.lessonBlocks, enhancement),
    relatedPracticeLinks: mergeQuadraticLinks(lesson.relatedPracticeLinks, [
      ...enhancement.links,
      ...bridgeLinks,
      ...maxMinDomainLinks,
      ...paramFunctionLinks,
      ...rootPlacementLinks,
      ...integerSolutionsPointsLinks,
      ...absoluteRadicalRationalLinks,
    ]),
    qualityTags: Array.from(new Set([...lesson.qualityTags, ...enhancement.tags])),
  };
}

